export interface ScopedAcBag {
  session: {
    user: { id: string };
    organization: { id: string; type: string } | null; // null: no active organization
  };
}

export interface ScopedAcRequestContext {
  bag: ScopedAcBag;
  roles: string[];
  permissions: string[];
  gateDb: GatedDb<SchemaTables>;
}

const bag: ScopedAcBag = {
  session: {
    user: { id: userId },
    organization: active ? { id: active.organizationId, type: active.orgType } : null,
  },
};
const roles = [...baselineRoles, ...(active?.roles ?? [])];
const permissions = engine.resolveEffectivePermissions(roles, bag);
return { bag, roles, permissions, gateDb: gatedDb(bag) };
